export const recipes = groups.flatMap(group => group.rows.map(row => {
  const [fixtureId, name, inputs, technique, output, review] = row.split('|')
  if (!review) throw new Error(`Incomplete authored recipe: ${fixtureId}`)
  return {
    fixtureId, name, inputs, technique, output, review,
    category: group.category, method: group.method, targetIds: group.targets,
    sourceIds: [...group.sources, ...(['public-release-brief', 'source-of-truth'].includes(fixtureId) ? ['m365'] : [])],
    context: [...group.context, ...({
      'public-release-brief': ['microsoft.edge'],
      'source-of-truth': ['microsoft.sharepoint', 'microsoft.onedrive'],
      'loop-collaboration': ['microsoft.loop'],
    }[fixtureId] ?? [])],
    taskType: 'prompt', format: 'text.plain',
  }
}))
